function fill(m){
const st=stats();
const set=(id,v)=>{const e=$(id);if(e)e.textContent=v};
set('mfDay',st.day);set('mfHour',String(st.hour).padStart(2,'0'));set('mfHq',st.hq);set('mfBld',st.buildings);
set('mfHer',st.heroes);set('mfCh',st.ch);set('mfAlm',st.alarms);
set('mfLife',st.lifeOn?'идёт':'выключена');
}
function open(){
let m=$('manifestModal');
if(!m){m=buildModal();document.body.appendChild(m)}
fill(m);
m.hidden=false;
requestAnimationFrame(()=>m.classList.add('show'));
}
function close(){
const m=$('manifestModal');
if(!m)return;
let done=false;
const fin=()=>{if(done)return;done=true;m.hidden=true;clearTimeout(fb);m.removeEventListener('transitionend',onEnd)};
const onEnd=e=>{if(e.target===m.querySelector('.mf-card'))fin()};
m.querySelector('.mf-card').addEventListener('transitionend',onEnd);
const fb=setTimeout(fin,600);
m.classList.remove('show');
}
let btn=$('manifestBtn');
if(!btn){
btn=el('button','manifest-btn','📦 СВОДКА');
btn.id='manifestBtn';
btn.style.cssText='position:absolute;left:8px;bottom:140px;z-index:28;background:rgba(10,14,18,.88);border:1px solid #22c55e;color:#22c55e;padding:5px 9px;border-radius:7px;font-size:10px;font-weight:800;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.4)';
btn.onclick=()=>open();
const sc=$('mainSc')||document.body;
sc.appendChild(btn);
}
window.__manifest={open:open,close:close,stats:stats};
